      "2000年前に皇帝であるエルメシアが興した歴史ある国家であり、支配下にある十三王家の君主は全員がエルメシアに忠誠を誓っている。軍事を含む全ての権力が皇帝に掌握され、各王家が自治を認められている国から税の徴収と各国間の調停を司り、過去ただの一度も反乱を許したことがない。",
