          "彼らが登場する魔導操騎（メイガス）は、他国での使用は機密漏洩罪にあたるほどの国家機密の兵器。普段は装飾品の魔法の宝石に空間収納されているが、本体は魔鋼製の外装に竜の筋繊維を駆動力とし、熱収束砲(ニュークリアカノン)に相当する高威力熱線を連射可能な、全高5mの鎧型のロボットになる。また、意思を宿し自ら適合者を探し求める、知恵ある兵器（インテリジェンスウェポン）であり、搭乗者はメイガスと感覚を共有して戦闘を行う。戦闘能力は最低でも特Aランク相当となり、エースにもなるとその存在値は50万を超える。",
