      "“三賢酔”計画における暴力装置としての、裏の組織。ロッゾ一族が衰退したことで纏まりがなくなった犯罪組織（七刃、賢人会、暗天衆、黒爪団など）を片っ端から潰して吸収することで統一された巨大な犯罪組織。裏社会の武力が集結する必要悪である一方で、落ちこぼれた者、虐げられた貧民の受け皿となる場所として機能し、優秀だと判断されれば魔国連邦での受け入れも計画されている。",
      "三首領に代わり、ボス役を元“三武仙”グレンダ・アトリー、元“緑の使徒”のジラードやアインが務め、この三名を始めとしたソウエイの部下も多数所属している。",
