          "帝国で密かに改造手術を受けさせた、自慢の部下達。個々の戦闘能力は最低でもAランクに達し、各種武装の扱いにも長けている。小型対戦車砲（ロケットランチャー）や携行式ガトリング砲といった、凶悪な武器の数々。それらに用いられる弾薬も通常のものにあらず、専門知識を得た者だけに使用を許可された、危険物取り扱い指定を受けた劇物。その威力は推して知るべし。",
