          "魔国連邦を筆頭とした周辺諸国による“四カ国通商連盟”と魔国連邦に敵愾心を持つロッゾ一族の生き残りを中心とした“西方総合商社”。この二つを競合させる事で、値を競り合い流通を奪い合う、武力を介在させない健全な競争の活性化も目指し、組織内では協力し合うように仕向け、組織が腐敗するのを予防する。また裏組織を利用することによる腐敗も“三賢酔”によって抑止される。",
